#Requires -Version 5.1
# feat-obras-mejoras.ps1
#
# MEJORAS IMPLEMENTADAS:
#
# 1. FILTRO MULTI-ESTADO
#    - Dropdown con checkboxes para seleccionar 1 o varios estados
#    - Botón X para limpiar la selección
#    - Muestra "N estados" cuando hay varios seleccionados
#    - Resaltado visual cuando hay estados activos
#
# 2. COLUMNA N.º PRESUPUESTO EN LISTADO
#    - Primera columna del listado en fuente monoespaciada
#    - Orden natural ascendente (P-20 antes que P-100)
#    - Sin presupuesto al final
#    - Criterio secundario: nombre de obra
#
# 3. CAMBIO DE ESTADO DESDE EL LISTADO
#    - Select inline con el color del estado como fondo
#    - Solo editable si puedeEditar (isAdmin || canDo("obras","editar"))
#    - Optimistic update: cambia en pantalla inmediatamente
#    - Si falla: revierte al estado anterior + alerta
#    - El trigger audit_obras de Supabase registra el cambio automáticamente
#      (valor anterior y nuevo en audit_log.valor_anterior/nuevo)
#    - RLS: ejecutar la migracion SQL incluida al final del script
#
# 4. PDF ACTUALIZADO
#    - Columnas: N.º Presupuesto | Cliente | Obra | Estado | Anotaciones
#    - Orden: Estado → N.º Presupuesto natural → Nombre
#    - Filtros multi-estado reflejados en la cabecera del PDF
#    - estadosFilterLabels: array de nombres de estados seleccionados
#
# RLS SQL (ejecutar en Supabase SQL Editor):
# -- Ejecutar en Supabase SQL Editor
# -- Ampliar obras_update para usuarios con permiso editar en obras o planificacion
# DROP POLICY IF EXISTS "obras_update" ON obras;
# CREATE POLICY "obras_update" ON obras FOR UPDATE USING (
#   get_user_role() = 'admin'
#   OR EXISTS (
#     SELECT 1 FROM users u
#     JOIN rol_permisos rp ON rp.rol_id = u.rol_id
#     WHERE u.id = auth.uid()
#       AND rp.pantalla IN ('obras', 'planificacion')
#       AND rp.editar = true
#   )
# );
# -- obras_insert tambien para usuarios con crear en obras
# DROP POLICY IF EXISTS "obras_insert" ON obras;
# CREATE POLICY "obras_insert" ON obras FOR INSERT WITH CHECK (
#   get_user_role() = 'admin'
#   OR EXISTS (
#     SELECT 1 FROM users u
#     JOIN rol_permisos rp ON rp.rol_id = u.rol_id
#     WHERE u.id = auth.uid()
#       AND rp.pantalla = 'obras'
#       AND rp.crear = true
#   )
# );

$ErrorActionPreference = "Stop"
$RepoPath = "C:\Users\lauro\Desktop\LOYNEK\ObrasPlan\obrasplan-mvp\obrasplan"
if (-not (Test-Path $RepoPath)) { Write-Host "ERROR" -ForegroundColor Red; exit 1 }
Set-Location $RepoPath
git pull --quiet 2>$null
Write-Host "" ; Write-Host "==> feat: obras mejoras multi-estado + presupuesto + cambio estado" -ForegroundColor Cyan

Write-Host "  -> src\app\obras\page.tsx" -ForegroundColor Gray
$dir = Split-Path -Parent (Join-Path $RepoPath "src\app\obras\page.tsx")
if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\obras\page.tsx"), $bytes)
Write-Host "  OK: 18 KB" -ForegroundColor Green

Write-Host "  -> src\app\api\informes\obras\route.ts" -ForegroundColor Gray
$dir = Split-Path -Parent (Join-Path $RepoPath "src\app\api\informes\obras\route.ts")
if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\api\informes\obras\route.ts"), $bytes)
Write-Host "  OK: 7 KB" -ForegroundColor Green

$page  = [System.IO.File]::ReadAllText((Join-Path $RepoPath "src\app\obras\page.tsx"), [System.Text.Encoding]::UTF8)
$route = [System.IO.File]::ReadAllText((Join-Path $RepoPath "src\app\api\informes\obras\route.ts"), [System.Text.Encoding]::UTF8)
if ($page.Contains("estadosFilter"))       { Write-Host "  OK: filtro multi-estado" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($page.Contains("naturalSort"))         { Write-Host "  OK: orden natural presupuesto" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($page.Contains("handleChangeEstado"))  { Write-Host "  OK: cambio estado inline" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($route.Contains("N.O PRESUPUESTO") -or $route.Contains("PRESUPUESTO")) { Write-Host "  OK: columna presupuesto en PDF" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($route.Contains("estadosFilterLabels")) { Write-Host "  OK: filtros multi-estado en PDF" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
Write-Host ""
Write-Host "  IMPORTANTE: Ejecutar SQL de migracion RLS en Supabase SQL Editor" -ForegroundColor Yellow
Write-Host "  (ver comentarios al inicio del script)"
Write-Host ""
Write-Host "  git add -A"
Write-Host '  git commit -m "feat: obras multi-estado + presupuesto + cambio estado inline + PDF mejorado"'
Write-Host "  git push"
